def estimate_kafka_telemetry_mb_s(wire_gbps=100, reduction_ratio=50):
    raw_mb_s = (wire_gbps * 1000) / 8  # 12,500 MB/s
    return round(raw_mb_s / reduction_ratio, 1)  # 250 MB/s

def process_telemetry_event(evt, ti_bloom, ml_scorer):
    if evt['dst_ip'] in ti_bloom:
        return {'verdict': 'THREAT_INTEL_HIT', 'severity': 'HIGH'}
    score = ml_scorer.predict(evt)
    return {'verdict': 'ANOMALY' if score > 0.85 else 'LOG_ONLY', 'score': score}

def check_ioc_two_stage(indicator, local_bloom, exact_rocksdb):
    if indicator not in local_bloom:
        return False  # Fast O(1) negative (99.9% of traffic)
    return exact_rocksdb.contains(indicator)  # Zero false-positive confirmation

def check_lateral_fanout(distinct_dst_ips, dst_port, is_scanner_allowlisted):
    if is_scanner_allowlisted:
        return False
    if dst_port in (445, 3389, 5985, 22) and distinct_dst_ips > 15:
        return True
    return False

def adapt_sensor_load(drop_pct, ebpf_config):
    if drop_pct > 1.0:
        ebpf_config.enable_udp_flood_sampling(rate=0.05)
        return 'DEGRADED_UDP_SAMPLED'
    return 'FULL_INSPECTION'

def execute_containment(host_ip, user_id, asset_tier, idempotency_key):
    if asset_tier == 'TIER_0_CRITICAL':
        return pagerduty.escalate(host_ip, 'ManualApprovalRequired')
    nac_api.quarantine_port(host_ip, key=idempotency_key)
    sso_api.revoke_sessions(user_id, key=idempotency_key)
    return 'CONTAINED'
